def evaluate_files():
    try:
        import pandas as pd
        import numpy as np

        ref_path = r"C:\Users\sandeeppawar\Downloads\aida-eval\data\file_generation_en\reference\FG_118\District Public Urban Primary School Quality Class Registration Statistics_organized_desensitized_res.xlsx"
        pred_path = r"C:\Users\sandeeppawar\Downloads\aida-eval\runs\aida-ctrl\work\FG_118\District Public Urban Primary School Quality Class Registration Statistics_organized_desensitized.xlsx"

        # Load Excel files
        ref_xl = pd.ExcelFile(ref_path, engine='openpyxl')
        pred_xl = pd.ExcelFile(pred_path, engine='openpyxl')

        # Check sheet names
        target_sheet = '小学Information Technology'

        if target_sheet not in ref_xl.sheet_names:
            return {"is_correct": False, "reason": f"Target sheet not in reference. Available: {ref_xl.sheet_names}"}

        if target_sheet not in pred_xl.sheet_names:
            return {"is_correct": False, "reason": f"Target sheet not in predicted. Available: {pred_xl.sheet_names}"}

        # Read sheets
        ref_df = pd.read_excel(ref_xl, sheet_name=target_sheet)
        pred_df = pd.read_excel(pred_xl, sheet_name=target_sheet)

        # Compare shapes
        if ref_df.shape != pred_df.shape:
            return {"is_correct": False, "reason": f"Shape mismatch: reference has {ref_df.shape}, predicted has {pred_df.shape}"}

        # Compare columns
        if list(ref_df.columns) != list(pred_df.columns):
            return {"is_correct": False, "reason": f"Column mismatch: ref cols={list(ref_df.columns)}, pred cols={list(pred_df.columns)}"}

        # Normalize and compare content
        def normalize_value(v):
            if pd.isna(v):
                return ""
            return str(v).strip()

        # Compare cell by cell (sample)
        mismatches = []
        sample_indices = list(range(min(10, len(ref_df))))

        for idx in sample_indices:
            for col in ref_df.columns:
                ref_val = normalize_value(ref_df.at[idx, col])
                pred_val = normalize_value(pred_df.at[idx, col])
                if ref_val != pred_val:
                    mismatches.append(f"Row {idx}, Col '{col}': ref='{ref_val}' vs pred='{pred_val}'")
                    if len(mismatches) >= 3:
                        break
            if len(mismatches) >= 3:
                break

        if mismatches:
            return {"is_correct": False, "reason": f"Content mismatch: {'; '.join(mismatches)}"}

        return {"is_correct": True, "reason": f"All checks passed: {ref_df.shape[0]} rows, {ref_df.shape[1]} columns match perfectly"}

    except Exception as e:
        import traceback
        return {"is_correct": False, "reason": f"Error during evaluation: {str(e)}, {traceback.format_exc()[:200]}"}

